/*
 * Samsung S5K4H8 (8 Mpix) MIPI CSI-2 Bayer sensor
 *
 * Copyright (C) 2026 Meizu fleet kernel port
 *
 * The Meizu M5c rear camera is a S5K4H8 module ("s5k4h8_mipi_raw" in the
 * vendor trees).  The register sequences below are a direct transcription of
 * the working MT6755/MT6735 vendor driver
 * (drivers/misc/mediatek/imgsensor/src/mt6755/s5k4h8_mipi_raw/
 *  s5k4h8mipi_Sensor.c): sensor_init(), preview_setting() and
 * normal_capture_setting(), with the vendor's 16 bit register writes split
 * into the two 8 bit accesses the sensor expects.
 *
 * The sensor has a 16 bit register address space and 8 bit registers, is
 * clocked by a 24 MHz MCLK and uses double data rate MIPI with four data
 * lanes.  Pixel array is 3280x2464, the visible output window of the vendor
 * modes is 3264x2448 (full) and 1632x1224 (2x2 binned preview).
 */

#include <linux/delay.h>
#include <linux/i2c.h>
#include <linux/module.h>
#include <linux/pm_runtime.h>

#include <media/v4l2-cci.h>
#include <media/v4l2-ctrls.h>
#include <media/v4l2-subdev.h>

#include "mtk-sensor-legacy.h"

#define S5K4H8_NAME		"s5k4h8"

#define S5K4H8_REG_CHIP_ID	0x0000
#define S5K4H8_CHIP_ID		0x4088
#define S5K4H8_REG_MODE_SELECT	0x0100
#define S5K4H8_MODE_STANDBY	0x00
#define S5K4H8_MODE_STREAMING	0x01
#define S5K4H8_REG_SOFT_RESET	0x0103
#define S5K4H8_REG_MIRROR	0x0101
#define S5K4H8_REG_COARSE_EXP	0x0202
#define S5K4H8_REG_ANALOG_GAIN	0x0204
#define S5K4H8_REG_FRAME_LENGTH	0x0340
#define S5K4H8_REG_LINE_LENGTH	0x0342
#define S5K4H8_REG_GROUP_PARAM	0x0104

#define S5K4H8_MCLK		24000000
#define S5K4H8_MCLK_INDEX	3	/* 24 MHz from the SoC CSI PLL */
#define S5K4H8_GAIN_MIN		32
#define S5K4H8_GAIN_MAX		1024	/* 32x in 1/32 units, vendor limit */
#define S5K4H8_VBLANK_MAX	(0xffff - 2480)

/*
 * The vendor driver programmes the mode, parks the sensor through the
 * "sleep mode" register and only then releases streaming; it also waits
 * 60 ms between the two halves of the mode table.
 */
#define S5K4H8_MODE_DELAY_US	60000

