static const char * const s5k4h8_supply_names[] = {
	"avdd",		/* VCAMA, analog 2.8 V */
	"dovdd",	/* VCAMIO, I/O 1.8 V */
	"dvdd",		/* VCAMD, core 1.2 V */
};

static int s5k4h8_set_gain(struct mtk_sensor *sensor, u32 gain)
{
	int ret = 0;

	/*
	 * Vendor gain2reg(): the register holds the gain in 1/32 units, i.e.
	 * 0x0200 is 1.0x.  Values outside 1x..32x are clamped as the vendor
	 * code does.
	 */
	gain = clamp_val(gain, S5K4H8_GAIN_MIN, S5K4H8_GAIN_MAX);

	ret = cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_ANALOG_GAIN),
			gain >> 8, NULL);
	if (ret)
		return ret;

	return cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_ANALOG_GAIN + 1),
			 gain & 0xff, NULL);
}

static int s5k4h8_set_exposure(struct mtk_sensor *sensor, u32 lines)
{
	int ret = 0;

	cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_GROUP_PARAM), 0x01,
		  &ret);
	cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_COARSE_EXP),
		  (lines >> 8) & 0xff, &ret);
	cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_COARSE_EXP + 1),
		  lines & 0xff, &ret);
	cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_GROUP_PARAM), 0x00,
		  &ret);

	return ret;
}

static int s5k4h8_set_flip(struct mtk_sensor *sensor, bool hflip, bool vflip)
{
	u8 val = (hflip ? 0x01 : 0x00) | (vflip ? 0x02 : 0x00);

	/* 0x0101: bit 0 mirror, bit 1 vertical flip (vendor set_mirror_flip) */
	return cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_MIRROR), val,
			 NULL);
}

static void s5k4h8_prepare(struct mtk_sensor *sensor,
			   const struct mtk_sensor_mode *mode)
{
	int ret = 0;

	/* Both vendor modes need the same settling gap before stream-on */
	(void)mode;

	cci_write(sensor->regmap, SENSOR_REG(S5K4H8_REG_MODE_SELECT),
		  S5K4H8_MODE_STANDBY, &ret);
	if (ret)
		dev_warn(sensor->dev, "failed to enter standby: %d\n", ret);
}

static const struct mtk_sensor_ops s5k4h8_ops = {
	.set_gain = s5k4h8_set_gain,
	.set_exposure = s5k4h8_set_exposure,
	.set_flip = s5k4h8_set_flip,
	.prepare = s5k4h8_prepare,
};

static int s5k4h8_probe(struct i2c_client *client)
{
	struct mtk_sensor *sensor;

	sensor = devm_kzalloc(&client->dev, sizeof(*sensor), GFP_KERNEL);
	if (!sensor)
		return -ENOMEM;

	sensor->name = S5K4H8_NAME;
	sensor->mbus_code = MEDIA_BUS_FMT_SGRBG10_1X10;
	sensor->modes = s5k4h8_modes;
	sensor->num_modes = ARRAY_SIZE(s5k4h8_modes);
	sensor->ops = &s5k4h8_ops;
	sensor->supply_names = s5k4h8_supply_names;
	sensor->num_supplies = ARRAY_SIZE(s5k4h8_supply_names);
	sensor->xclk_rate = S5K4H8_MCLK;
	sensor->power_up_delay_ms = 10;
	sensor->mode_delay_us = S5K4H8_MODE_DELAY_US;
	sensor->init_regs = s5k4h8_init_regs;
	sensor->num_init_regs = ARRAY_SIZE(s5k4h8_init_regs);
	sensor->id_reg = S5K4H8_REG_CHIP_ID;
	sensor->id_val = S5K4H8_CHIP_ID;
	sensor->gain_min = S5K4H8_GAIN_MIN;
	sensor->gain_max = S5K4H8_GAIN_MAX;

	return mtk_sensor_register(sensor, client);
}

static void s5k4h8_remove(struct i2c_client *client)
{
	struct v4l2_subdev *sd = i2c_get_clientdata(client);

	v4l2_subdev_cleanup(sd);
	media_entity_cleanup(&sd->entity);
}

static const struct of_device_id s5k4h8_of_match[] = {
	{ .compatible = "samsung,s5k4h8" },
	{ }
};
MODULE_DEVICE_TABLE(of, s5k4h8_of_match);

static struct i2c_driver s5k4h8_driver = {
	.driver = {
		.name = "s5k4h8",
		.of_match_table = s5k4h8_of_match,
	},
	.probe = s5k4h8_probe,
	.remove = s5k4h8_remove,
};

module_i2c_driver(s5k4h8_driver);

